// Code generated by Typeship. DO NOT EDIT.

// Offline smoke and contract tests for this CLI's generated command
// surface: root help and version, resource and operation routing, flag
// parsing, and the usage and confirmation failures that must stop before
// any request is sent. Every case is derived from the generated command
// table in ops.go. The tests use only the standard library and the paired
// SDK, and they never contact the network or read stored credentials.
//
// Run them from this directory with `go test ./...`.

package main

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	sdk "github.com/typeship-ax/cli/internal/client"
)

// errOffline fails any request that reaches the test transport.
var errOffline = errors.New("offline test: the CLI attempted a network request")

// offlineTransport counts and fails every request that reaches it.
type offlineTransport struct {
	requests int
}

// RoundTrip records the attempted request and fails it without network I/O.
func (t *offlineTransport) RoundTrip(*http.Request) (*http.Response, error) {
	t.requests++
	return nil, errOffline
}

// offline isolates t from saved configuration and output-mode variables, and
// replaces the default HTTP transport for the rest of the test. The test fails
// if any request reaches that transport.
func offline(t *testing.T) {
	t.Helper()
	dir := t.TempDir()
	t.Setenv("HOME", dir)
	t.Setenv("XDG_CONFIG_HOME", dir)
	for _, suffix := range []string{"_AGENT", "_HUMAN", "_COLOR", "_EXPLICIT_NONINTERACTIVE", "_MODE"} {
		t.Setenv(authPrefix+suffix, "")
	}
	for _, name := range []string{mcpReadOnlyEnv, mcpToolsEnv} {
		t.Setenv(name, "")
	}
	transport := &offlineTransport{}
	previous := http.DefaultTransport
	http.DefaultTransport = transport
	t.Cleanup(func() {
		http.DefaultTransport = previous
		if transport.requests > 0 {
			t.Errorf("%d request(s) reached the network; these tests must stay offline", transport.requests)
		}
	})
}

// runCLI runs the CLI in-process and returns its exit code, stdout, and stderr.
func runCLI(args ...string) (int, string, string) {
	var stdout, stderr bytes.Buffer
	code := run(args, &stdout, &stderr)
	return code, stdout.String(), stderr.String()
}

// expectFailure runs args in JSON mode, checks the exit code and the first
// issue code of the structured failure on stderr, and returns its message.
func expectFailure(t *testing.T, exit int, issue string, args ...string) string {
	t.Helper()
	line := strings.Join(args, " ")
	code, stdout, stderr := runCLI(append([]string{"--json"}, args...)...)
	if code != exit {
		t.Errorf("%s: exit %d, want %d\nstdout: %s\nstderr: %s", line, code, exit, stdout, stderr)
		return ""
	}
	lines := strings.Split(strings.TrimSpace(stderr), "\n")
	var failure struct {
		Issues []struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"issues"`
	}
	if err := json.Unmarshal([]byte(lines[len(lines)-1]), &failure); err != nil || len(failure.Issues) == 0 {
		t.Errorf("%s: stderr is not a structured failure: %q", line, stderr)
		return ""
	}
	if failure.Issues[0].Code != issue {
		t.Errorf("%s: issue %s (%s), want %s", line, failure.Issues[0].Code, failure.Issues[0].Message, issue)
	}
	return failure.Issues[0].Message
}

// commandLine returns a new argument list that routes to op, followed by
// extra.
func commandLine(op opDef, extra ...string) []string {
	return append([]string{op.Resource, op.Command}, extra...)
}

func TestOperationFlagNames(t *testing.T) {
	op := opDef{
		Params:   []paramDef{paramDef{Flag: "name", Kind: "query"}},
		BodyKind: "binary",
		Select:   true,
	}
	names := operationFlagNames(op)
	for _, want := range []string{"name", "all", "color", "data", "debug", "fields", "format", "help", "json", "non-interactive", "out", "read-only", "tools", "validate", "yes", "force", "file", "select"} {
		if !containsStr(names, want) {
			t.Errorf("operationFlagNames() is missing %q: %v", want, names)
		}
	}
	binaryNames := operationFlagNames(opDef{BodyKind: "binary"})
	if !containsStr(binaryNames, "file") || containsStr(binaryNames, "select") {
		t.Errorf("binary operation has incorrect conditional flags: %v", binaryNames)
	}
	selectNames := operationFlagNames(opDef{Select: true})
	if containsStr(selectNames, "file") || !containsStr(selectNames, "select") {
		t.Errorf("selectable operation has incorrect conditional flags: %v", selectNames)
	}
	plainNames := operationFlagNames(opDef{})
	if containsStr(plainNames, "file") || containsStr(plainNames, "select") {
		t.Errorf("plain operation includes conditional flags: %v", plainNames)
	}
}

// samplePositionals returns one placeholder value per path parameter of op.
func samplePositionals(op opDef) []string {
	values := []string{}
	for i := range pathParams(op) {
		values = append(values, "value-"+strconv.Itoa(i+1))
	}
	return values
}

// parserFlag reports whether the operation parser handles name itself rather
// than as one of op's parameters.
func parserFlag(op opDef, name string) bool {
	switch name {
	case "data", "fields", "out", "all", "help", "json", "non-interactive", "debug", "validate", "dry-run", "yes", "force", "mode", "format", "color", "read-only", "tools":
		return true
	case "file":
		return op.BodyKind == "binary"
	case "select":
		return op.Select
	}
	return containsStr(authFlags, name)
}

// invalidValue returns a value that p's type or enum rejects before a request
// is built, or an empty string when the CLI accepts any text for p.
func invalidValue(p paramDef) string {
	kind, enum := p.Type, p.Enum
	if kind == "array" {
		kind, enum = p.ItemType, p.ItemEnum
	}
	if kind != "string" && kind != "number" && kind != "boolean" {
		return ""
	}
	switch {
	case len(enum) > 0:
		return "typeship-test-unlisted-value"
	case kind == "number":
		return "typeship-test-not-a-number"
	case kind == "boolean":
		return "typeship-test-not-a-boolean"
	}
	return ""
}

// TestRootHelp checks that each root help spelling prints the generated root
// help, and that the root help names every resource.
func TestRootHelp(t *testing.T) {
	offline(t)
	for _, arg := range []string{"--help", "-h", "help"} {
		code, stdout, stderr := runCLI(arg)
		if code != 0 || stdout != rootHelp || stderr != "" {
			t.Errorf("%s: exit %d, stdout %q, stderr %q", arg, code, stdout, stderr)
		}
	}
	for _, resource := range resourceOrder {
		if !strings.Contains(rootHelp, resource) {
			t.Errorf("root help does not list resource %q", resource)
		}
	}
}

