// TestHelpJSON checks that the bounded machine-readable index names this CLI,
// its version, and every resource in order.
func TestHelpJSON(t *testing.T) {
	offline(t)
	code, stdout, stderr := runCLI("help", "--json")
	if code != 0 {
		t.Fatalf("help --json: exit %d, stderr %q", code, stderr)
	}
	var help struct {
		SchemaVersion string `json:"schema_version"`
		Detail        string `json:"detail"`
		Name          string `json:"name"`
		Version       string `json:"version"`
		CommandCount  int    `json:"command_count"`
		Resources     []struct {
			Resource     string `json:"resource"`
			CommandCount int    `json:"command_count"`
		} `json:"resources"`
	}
	if err := json.Unmarshal([]byte(stdout), &help); err != nil {
		t.Fatalf("help --json is not JSON: %v\n%s", err, stdout)
	}
	if help.Name != bin || help.Version != version {
		t.Errorf("help --json names %s %s, want %s %s", help.Name, help.Version, bin, version)
	}
	if help.SchemaVersion != "3" || help.Detail != "index" || help.CommandCount != len(ops) {
		t.Errorf("help --json index metadata = %s/%s/%d; want 3/index/%d", help.SchemaVersion, help.Detail, help.CommandCount, len(ops))
	}
	if len(help.Resources) != len(resourceOrder) {
		t.Fatalf("help --json resources = %d; want %d", len(help.Resources), len(resourceOrder))
	}
	for i, resource := range resourceOrder {
		count := 0
		for _, op := range ops {
			if op.Resource == resource {
				count++
			}
		}
		if help.Resources[i].Resource != resource || help.Resources[i].CommandCount != count {
			t.Errorf("help --json resource[%d] = %+v; want %s with %d commands", i, help.Resources[i], resource, count)
		}
	}
}

// TestHelpJSONDetails checks exhaustive and targeted command metadata.
func TestHelpJSONDetails(t *testing.T) {
	offline(t)
	code, stdout, stderr := runCLI("help", "--json", "--all")
	if code != 0 {
		t.Fatalf("help --json --all: exit %d, stderr %q", code, stderr)
	}
	var all struct {
		Resources []struct {
			Resource string `json:"resource"`
			Commands []struct {
				Command        string `json:"command"`
				Safety         string `json:"safety"`
				ExampleCommand string `json:"example_command"`
				Flags          []struct {
					Flag string `json:"flag"`
				} `json:"flags"`
			} `json:"commands"`
		} `json:"resources"`
	}
	if err := json.Unmarshal([]byte(stdout), &all); err != nil {
		t.Fatalf("help --json --all is not JSON: %v", err)
	}
	found := 0
	for _, resource := range all.Resources {
		if len(resource.Commands) == 0 {
			t.Errorf("help --json --all resource %q has no commands", resource.Resource)
		}
		for _, command := range resource.Commands {
			found++
			if len(command.Flags) == 0 || command.Safety == "" || command.ExampleCommand == "" {
				t.Errorf("%s %s: missing flags, safety, or example metadata", resource.Resource, command.Command)
			}
		}
	}
	if found != len(ops) {
		t.Errorf("help --json --all has %d commands; want %d", found, len(ops))
	}
	if len(ops) == 0 {
		return
	}
	op := ops[0]
	code, stdout, stderr = runCLI("help", op.Resource, "--json")
	if code != 0 {
		t.Fatalf("help %s --json: exit %d, stderr %q", op.Resource, code, stderr)
	}
	var resource struct {
		Commands []struct {
			Command string `json:"command"`
		} `json:"commands"`
	}
	if err := json.Unmarshal([]byte(stdout), &resource); err != nil || len(resource.Commands) == 0 || resource.Commands[0].Command != op.Command {
		t.Errorf("targeted resource help does not list %s first: %s", op.Command, stdout)
	}
	code, stdout, stderr = runCLI("help", op.Resource, op.Command, "--json")
	if code != 0 {
		t.Fatalf("help %s %s --json: exit %d, stderr %q", op.Resource, op.Command, code, stderr)
	}
	var operation struct {
		Command        string `json:"command"`
		ExampleCommand string `json:"example_command"`
		Flags          []struct {
			Flag string `json:"flag"`
		} `json:"flags"`
	}
	if err := json.Unmarshal([]byte(stdout), &operation); err != nil || operation.Command != op.Command || operation.ExampleCommand == "" || len(operation.Flags) == 0 {
		t.Errorf("targeted operation help is incomplete: %s", stdout)
	}
}

// TestResourceHelp checks that each resource prints its help with or without
// a help flag, and that the help lists every command of the resource.
func TestResourceHelp(t *testing.T) {
	offline(t)
	for _, resource := range resourceOrder {
		help, ok := resourceHelp[resource]
		if !ok {
			t.Errorf("resource %q has no help", resource)
			continue
		}
		for _, extra := range [][]string{nil, []string{"--help"}, []string{"-h"}} {
			args := append([]string{resource}, extra...)
			code, stdout, stderr := runCLI(args...)
			if code != 0 || stdout != help || stderr != "" {
				t.Errorf("%s: exit %d, stdout %q, stderr %q", strings.Join(args, " "), code, stdout, stderr)
			}
		}
	}
	for _, op := range ops {
		if !containsStr(resourceOrder, op.Resource) {
			t.Errorf("%s %s: resource is missing from the resource list", op.Resource, op.Command)
		}
		if !strings.Contains(resourceHelp[op.Resource], op.Command) {
			t.Errorf("%s %s: resource help does not list the command", op.Resource, op.Command)
		}
	}
}

// TestOperationRouting checks that every command and alias routes to its own
// operation and prints that operation's help, and that an unknown command
// under each resource is a usage error.
func TestOperationRouting(t *testing.T) {
	offline(t)
	for i := range ops {
		op := &ops[i]
		name := op.Resource + " " + op.Command
		if findOp(op.Resource, op.Command) != op {
			t.Errorf("%s: the command does not route to its own operation", name)
		}
		if op.CommandAlias != "" && findOp(op.Resource, op.CommandAlias) != op {
			t.Errorf("%s: alias %q does not route to the operation", name, op.CommandAlias)
		}
		for _, flag := range []string{"--help", "-h"} {
			code, stdout, stderr := runCLI(op.Resource, op.Command, flag)
			if code != 0 || stdout != op.Help || stderr != "" {
				t.Errorf("%s %s: exit %d, stdout %q, stderr %q", name, flag, code, stdout, stderr)
			}
		}
	}
	for _, resource := range resourceOrder {
		expectFailure(t, 2, "UNKNOWN_COMMAND", resource, "typeship-test-unknown-command")
	}
}

// TestOperationHelpMetadata checks that each operation's help names the
// command, every positional argument and flag, and the confirmation flag of a
// destructive operation.
func TestOperationHelpMetadata(t *testing.T) {
	for _, op := range ops {
		name := op.Resource + " " + op.Command
		if !strings.HasPrefix(op.Help, bin+" "+name+" ") {
			t.Errorf("%s: help does not start with the command: %q", name, op.Help)
		}
		for _, p := range op.Params {
			want := "--" + p.Flag
			if p.Kind == "path" {
				want = "<" + p.Name + ">"
			}
			if !strings.Contains(op.Help, want) {
				t.Errorf("%s: help does not mention %s", name, want)
			}
		}
		if op.Safety == "destructive" && !strings.Contains(op.Help, "--yes") {
			t.Errorf("%s: destructive help does not mention --yes", name)
		}
	}
}

// TestParseOperationArguments checks that each operation's parser keeps
// positional arguments in order and reads every flag in its separate, equals,
// boolean, or list form.
func TestParseOperationArguments(t *testing.T) {
	for _, op := range ops {
		name := op.Resource + " " + op.Command
		positionals := samplePositionals(op)
		args := append([]string{}, positionals...)
		want := map[string]opFlagValue{}
		for i, p := range op.Params {
			if p.Kind == "path" || parserFlag(op, p.Flag) {
				continue
			}
			value := "value-" + strconv.Itoa(i+1)
			switch {
			case p.Type == "boolean":
				args = append(args, "--"+p.Flag)
				want[p.Flag] = opFlagValue{scalar: "true"}
			case p.Type == "array":
				args = append(args, "--"+p.Flag, value+",second")
				want[p.Flag] = opFlagValue{list: []string{value, "second"}, isList: true}
			case i%2 == 0:
				args = append(args, "--"+p.Flag+"="+value)
				want[p.Flag] = opFlagValue{scalar: value}
			default:
				args = append(args, "--"+p.Flag, value)
				want[p.Flag] = opFlagValue{scalar: value}
			}
		}
		gotPositionals, values, data, help, err := parseOpArgs(op, args)
		if err != nil || help || data != nil {
			t.Errorf("%s %q: err %v, help %t, data %q", name, args, err, help, data)
			continue
		}
		if strings.Join(gotPositionals, "\n") != strings.Join(positionals, "\n") {
			t.Errorf("%s: positionals %q, want %q", name, gotPositionals, positionals)
		}
		if len(values) != len(want) {
			t.Errorf("%s: parsed %d flag(s), want %d", name, len(values), len(want))
		}
		for flag, expected := range want {
			got, ok := values[flag]
			if !ok || got.scalar != expected.scalar || got.isList != expected.isList || strings.Join(got.list, "\n") != strings.Join(expected.list, "\n") {
				t.Errorf("%s --%s: parsed %+v, want %+v", name, flag, got, expected)
			}
		}
		rest, _, _, _, err := parseOpArgs(op, []string{"--", "--typeship-test-literal"})
		if err != nil || len(rest) != 1 || rest[0] != "--typeship-test-literal" {
			t.Errorf("%s: -- does not end flag parsing: %q, %v", name, rest, err)
		}
		if _, _, _, help, _ := parseOpArgs(op, []string{"--help"}); !help {
			t.Errorf("%s: --help is not recognized", name)
		}
	}
}

// TestUnknownFlags checks that an unknown flag is a usage error for every
// operation.
func TestUnknownFlags(t *testing.T) {
	offline(t)
	for _, op := range ops {
		expectFailure(t, 2, "UNKNOWN_FLAG", commandLine(op, append(samplePositionals(op), "--typeship-test-unknown-flag", "value")...)...)
	}
}

// TestMissingArguments checks that a wrong number of positional arguments, a
// missing required flag, or a missing required body is a usage error that
// names what is missing.
func TestMissingArguments(t *testing.T) {
	offline(t)
	for _, op := range ops {
		if len(pathParams(op)) > 0 {
			expectFailure(t, 2, "MISSING_ARGUMENT", commandLine(op, "--yes")...)
		}
		expectFailure(t, 2, "MISSING_ARGUMENT", commandLine(op, append(samplePositionals(op), "typeship-test-extra", "--yes")...)...)
		required := []string{}
		for _, p := range op.Params {
			if p.Kind != "path" && p.Required {
				required = append(required, "--"+p.Flag)
			}
		}
		if len(required) == 0 && !(op.BodyStyle == "data" && op.BodyRequired) {
			continue
		}
		message := expectFailure(t, 2, "MISSING_ARGUMENT", commandLine(op, append(samplePositionals(op), "--yes")...)...)
		for _, flag := range required {
			if !strings.Contains(message, flag) {
				t.Errorf("%s %s: %q does not name %s", op.Resource, op.Command, message, flag)
			}
		}
	}
}

func TestParseNamedCredentials(t *testing.T) {
	for _, data := range []string{"", "{", "null", "[]", `{"typeship-unknown-scheme": "secret"}`, strings.Repeat(" ", 1_048_577)} {
		if _, err := parseNamedCredentials([]byte(data)); err == nil {
			t.Errorf("accepted invalid credential document of length %d", len(data))
		}
	}
	if parsed, err := parseNamedCredentials([]byte("{}")); err != nil || len(parsed) != 0 {
		t.Fatalf("empty object: credentials %v, error %v", parsed, err)
	}
	for name, scheme := range namedCredentialSchemes {
		t.Run(name, func(t *testing.T) {
			var valid any = "test-token"
			want := namedCredential{Value: "test-token"}
			invalid := []any{nil, true, 42, "", "unsafe\r\nvalue", "unsafe\x00value", map[string]string{"token": "secret"}}
			if scheme.Kind == "basic" {
				valid = map[string]string{"username": "test-user", "password": "test-password"}
				want = namedCredential{Username: "test-user", Password: "test-password", Basic: true}
				invalid = []any{nil, "token", map[string]any{"username": "user"}, map[string]any{"username": "", "password": "pass"}, map[string]any{"username": "user", "password": 42}, map[string]any{"username": "user:name", "password": "pass"}, map[string]any{"username": "user", "password": "pass", "extra": "value"}}
			} else if scheme.Kind == "bearer" {
				invalid = append(invalid, "two tokens", "tab\ttoken")
			}
			if scheme.Kind != "basic" {
				for control := rune(0); control <= 0x1f; control++ {
					invalid = append(invalid, "unsafe"+string(control)+"value")
				}
				invalid = append(invalid, "unsafe\x7fvalue")
				allowed := "test-token-é"
				if scheme.Kind != "bearer" {
					allowed = "test key é"
				}
				data, err := json.Marshal(map[string]string{name: allowed})
				if err != nil {
					t.Fatal(err)
				}
				if parsed, err := parseNamedCredentials(data); err != nil || parsed[name].Value != allowed {
					t.Fatalf("allowed token: got %v, error %v", parsed, err)
				}
			}
			data, err := json.Marshal(map[string]any{name: valid})
			if err != nil {
				t.Fatal(err)
			}
			parsed, err := parseNamedCredentials(data)
			if err != nil || len(parsed) != 1 || parsed[name] != want {
				t.Fatalf("valid credential: got %v, error %v", parsed, err)
			}
			for i, value := range invalid {
				data, err := json.Marshal(map[string]any{name: value})
				if err != nil {
					t.Fatal(err)
				}
				if _, err := parseNamedCredentials(data); err == nil {
					t.Errorf("accepted invalid credential case %d", i)
				}
			}
		})
	}
}

func TestNamedCredentialSourcesAndPrecedence(t *testing.T) {
	offline(t)
	for _, flag := range authScalarFlags {
		t.Setenv(authCredentialEnvs[flag], "")
	}
	t.Setenv(namedCredentialsEnv, "")
	for name, scheme := range namedCredentialSchemes {
		t.Run(name, func(t *testing.T) {
			value := func(label string) any {
				if scheme.Kind == "basic" {
					return map[string]string{"username": label, "password": "test-password"}
				}
				return label
			}
			document := func(label string) []byte {
				data, err := json.Marshal(map[string]any{name: value(label)})
				if err != nil {
					t.Fatal(err)
				}
				return data
			}
			file := filepath.Join(t.TempDir(), "credentials.json")
			if err := os.WriteFile(file, document("flag"), 0600); err != nil {
				t.Fatal(err)
			}
			t.Setenv(namedCredentialsEnv, string(document("env")))
			args := []string{"--credentials", "@" + file}
			envNamed, flagNamed, err := readNamedCredentialSources(args)
			if err != nil {
				t.Fatal(err)
			}
			stored := storedAuth{}
			if err := json.Unmarshal(document("saved"), &stored.Named); err != nil {
				t.Fatal(err)
			}
			for _, source := range []struct {
				label string
				env   map[string]namedCredential
				flags map[string]namedCredential
			}{
				{"saved", nil, nil},
				{"env", envNamed, nil},
				{"flag", envNamed, flagNamed},
			} {
				merged, err := mergeNamedCredentialSources(nil, stored, source.env, source.flags)
				got := merged[name].Value
				if scheme.Kind == "basic" {
					got = merged[name].Username
				}
				if err != nil || got != source.label {
					t.Errorf("%s precedence: got %q, error %v", source.label, got, err)
				}
			}
			if _, _, err := readNamedCredentialSources(append(args, "--credentials", "@"+file)); err == nil {
				t.Error("accepted duplicate --credentials flags")
			}
			t.Setenv(namedCredentialsEnv, "{")
			if _, _, err := readNamedCredentialSources(args); err == nil {
				t.Error("accepted malformed environment credentials despite a valid flag")
			}
		})
	}
}

func TestNamedCredentialSelectorRedaction(t *testing.T) {
	offline(t)
	for _, flag := range authScalarFlags {
		t.Setenv(authCredentialEnvs[flag], "")
	}
	t.Setenv(authPrefix+"_PASSWORD", "")
	t.Setenv(namedCredentialsEnv, "")
	previous := activeNamedCredentialValues
	defer func() { activeNamedCredentialValues = previous }()
	for name, scheme := range namedCredentialSchemes {
		t.Run(name, func(t *testing.T) {
			secrets := []string{"named-secret/+="}
			var value any = secrets[0]
			if scheme.Kind == "basic" {
				secrets = []string{"named-user", "named-password/+="}
				value = map[string]string{"username": secrets[0], "password": secrets[1]}
			}
			data, err := json.Marshal(map[string]any{name: value})
			if err != nil {
				t.Fatal(err)
			}
			file := filepath.Join(t.TempDir(), "credentials.json")
			if err := os.WriteFile(file, data, 0600); err != nil {
				t.Fatal(err)
			}
			_, parsed, err := readNamedCredentialSources([]string{"--credentials", "@" + file})
			if err != nil {
				t.Fatal(err)
			}
			activeNamedCredentialValues = namedCredentialSecrets(parsed)
			for _, selector := range []string{"-", "@" + file} {
				for _, args := range [][]string{
					{"--credentials", selector},
					{"--credentials=" + selector},
				} {
					text := "Use --credentials " + selector + " or --help: " + strings.Join(secrets, " ")
					got := redact(text, args)
					want := "Use --credentials " + selector + " or --help: " + strings.TrimSpace(strings.Repeat("[REDACTED] ", len(secrets)))
					if got != want {
						t.Errorf("redaction: got %q, want %q", got, want)
					}
				}
			}
		})
	}
}

func TestNamedCredentialSourceCacheIsInvocationScoped(t *testing.T) {
	if len(namedCredentialSchemes) == 0 {
		t.Skip("API declares no named credentials")
	}
	name, scheme := "", namedCredentialScheme{}
	for candidate, configured := range namedCredentialSchemes {
		name, scheme = candidate, configured
		break
	}
	document := func(value string) []byte {
		var credential any = value
		if scheme.Kind == "basic" {
			credential = map[string]string{"username": value, "password": "test-password"}
		}
		data, err := json.Marshal(map[string]any{name: credential})
		if err != nil {
			t.Fatal(err)
		}
		return data
	}
	stdinFile := func(value string) *os.File {
		t.Helper()
		path := filepath.Join(t.TempDir(), "credentials.json")
		if err := os.WriteFile(path, document(value), 0600); err != nil {
			t.Fatal(err)
		}
		file, err := os.Open(path)
		if err != nil {
			t.Fatal(err)
		}
		return file
	}
	value := func(named map[string]namedCredential) string {
		if scheme.Kind == "basic" {
			return named[name].Username
		}
		return named[name].Value
	}
	t.Setenv(namedCredentialsEnv, "")
	originalStdin := os.Stdin
	defer func() { os.Stdin = originalStdin }()

	firstStdin := stdinFile("first-token")
	os.Stdin = firstStdin
	firstCtx := withNamedCredentialSourceCache(context.Background())
	_, first, err := invocationNamedCredentialSources(firstCtx, []string{"--credentials", "-"})
	if closeErr := firstStdin.Close(); closeErr != nil {
		t.Fatal(closeErr)
	}
	if err != nil || value(first) != "first-token" {
		t.Fatalf("first invocation credentials: got %q, error %v", value(first), err)
	}
	_, cached, err := invocationNamedCredentialSources(firstCtx, []string{"--credentials", "-"})
	if err != nil || value(cached) != "first-token" {
		t.Fatalf("cached invocation credentials: got %q, error %v", value(cached), err)
	}

	secondStdin := stdinFile("second-token")
	os.Stdin = secondStdin
	defer secondStdin.Close()
	_, second, err := invocationNamedCredentialSources(withNamedCredentialSourceCache(context.Background()), []string{"--credentials", "-"})
	if err != nil || value(second) != "second-token" {
		t.Fatalf("second invocation credentials: got %q, error %v", value(second), err)
	}
}

func TestNamedCredentialAlternativesPreflight(t *testing.T) {
	offline(t)
	for _, flag := range authScalarFlags {
		t.Setenv(authCredentialEnvs[flag], "")
	}
	t.Setenv(namedCredentialsEnv, "")
	alternative := []string{}
	named := map[string]namedCredential{}
	for name := range namedCredentialSchemes {
		alternative = append(alternative, "credentials."+name)
		named[name] = namedCredential{Value: "test-token"}
	}
	if len(alternative) == 0 {
		t.Skip("this CLI has no supported named credential schemes")
	}
	op := opDef{Auth: "required", CredentialOptions: [][]string{alternative}}
	_, err := authOptions(context.Background(), nil, &op, nil)
	var missing *missingCredentialsError
	if !errors.As(err, &missing) {
		t.Fatalf("no credentials: got %v, want missingCredentialsError", err)
	}
	if got := missingCredentialAlternatives(nil, &op, storedAuth{}, named); len(got) != 0 {
		t.Fatalf("complete AND alternative rejected: %v", got)
	}
	delete(named, strings.TrimPrefix(alternative[0], "credentials."))
	if got := missingCredentialAlternatives(nil, &op, storedAuth{}, named); len(got) == 0 {
		t.Fatal("incomplete AND alternative accepted")
	}
	if len(alternative) > 1 {
		op.CredentialOptions = [][]string{alternative, {alternative[1]}}
		if got := missingCredentialAlternatives(nil, &op, storedAuth{}, named); len(got) != 0 {
			t.Fatalf("complete OR alternative rejected: %v", got)
		}
	}
}

// TestDestructiveConfirmation checks that every destructive operation asks
// for confirmation instead of sending its request.
func TestDestructiveConfirmation(t *testing.T) {
	offline(t)
	for _, flag := range authScalarFlags {
		t.Setenv(authCredentialEnvs[flag], "test-credential")
	}
	if len(namedCredentialSchemes) > 0 {
		named := map[string]any{}
		for name, scheme := range namedCredentialSchemes {
			if scheme.Kind == "basic" {
				named[name] = map[string]string{"username": "test-user", "password": "test-password"}
			} else {
				named[name] = "test-credential"
			}
		}
		data, err := json.Marshal(named)
		if err != nil {
			t.Fatal(err)
		}
		t.Setenv(namedCredentialsEnv, string(data))
	}
	checked := 0
	for _, op := range ops {
		if op.Safety != "destructive" {
			continue
		}
		checked++
		expectFailure(t, 2, "CONFIRMATION_REQUIRED", commandLine(op, samplePositionals(op)...)...)
	}
	if checked == 0 {
		t.Skip("this CLI has no destructive operations")
	}
}

// TestInvalidFlagValues checks that a value a flag's type or enum rejects
// fails while the request is being built, with an error that names the flag.
// The client is unconfigured, so a value that skipped validation would fail
// at the SDK call with a different error instead of sending a request.
func TestInvalidFlagValues(t *testing.T) {
	offline(t)
	client := &sdk.Client{}
	checked := 0
	for _, op := range ops {
		// A raw request body is read before the flags.
		if op.BodyStyle == "data" {
			continue
		}
		for _, p := range op.Params {
			bad := invalidValue(p)
			if p.Kind == "path" || parserFlag(op, p.Flag) || bad == "" {
				continue
			}
			checked++
			value := opFlagValue{scalar: bad}
			if p.Type == "array" {
				value = opFlagValue{list: []string{bad}, isList: true}
			}
			_, err := invoke(client, context.Background(), op, samplePositionals(op), map[string]opFlagValue{p.Flag: value}, nil)
			var usage *usageError
			if err == nil || !strings.Contains(err.Error(), "--"+p.Flag) || !errors.As(err, &usage) {
				t.Errorf("%s %s --%s %q: err %v, want a usage error naming the flag", op.Resource, op.Command, p.Flag, bad, err)
			}
		}
	}
	if checked == 0 {
		t.Skip("no flag of this CLI has a locally checked type")
	}
}

// TestMalformedDataIsUsage checks that malformed --data JSON is a local usage
// error, exit 2, for every operation with a JSON body, without a request.
func TestMalformedDataIsUsage(t *testing.T) {
	offline(t)
	checked := 0
	for _, op := range ops {
		if op.BodyKind != "json" || op.BodyStyle == "" || hasRequiredFlag(op) {
			continue
		}
		checked++
		message := expectFailure(t, 2, "INVALID_USAGE", append(commandLine(op, samplePositionals(op)...), "--data", "{not json", "--yes")...)
		if !strings.HasPrefix(message, "--data: invalid JSON") {
			t.Errorf("%s %s: message %q, want one naming --data", op.Resource, op.Command, message)
		}
	}
	if checked == 0 {
		t.Skip("no operation of this CLI takes a JSON body without required flags")
	}
}

// TestDryRunPreview captures the fully resolved SDK request without allowing
// any API transport to run, and checks redaction, multipart files, and input
// validation.
func TestDryRunPreview(t *testing.T) {
	if findOp("accounts", "create") == nil {
		t.Skip("dry-run fixture operations are unavailable")
	}
	offline(t)
	t.Setenv("ACME_TOKEN", "")
	code, stdout, stderr := runCLI("--dry-run", "accounts", "create", "--name", "Preview Account", "--token", "preview-secret")
	if code != 0 || stderr != "" {
		t.Fatalf("typed preview: exit %d, stdout %q, stderr %q", code, stdout, stderr)
	}
	if !strings.Contains(stdout, `"body":`) {
		t.Errorf("typed preview omitted the request body field: %s", stdout)
	}
	var preview struct {
		DryRun  bool                `json:"dry_run"`
		Method  string              `json:"method"`
		URL     string              `json:"url"`
		Headers map[string][]string `json:"headers"`
		Body    string              `json:"body"`
	}
	if err := json.Unmarshal([]byte(stdout), &preview); err != nil {
		t.Fatalf("typed preview is not JSON: %v\n%s", err, stdout)
	}
	if !preview.DryRun || preview.Method != http.MethodPost || !strings.HasSuffix(preview.URL, "/v1/accounts") ||
		!strings.Contains(preview.Body, `"name":"Preview Account"`) ||
		len(preview.Headers["Authorization"]) != 1 || preview.Headers["Authorization"][0] != "[REDACTED]" ||
		strings.Contains(stdout, "preview-secret") {
		t.Errorf("typed preview did not resolve and redact the request: %s", stdout)
	}

	filePath := filepath.Join(t.TempDir(), "preview.txt")
	if err := os.WriteFile(filePath, []byte("avatar-preview-data"), 0600); err != nil {
		t.Fatal(err)
	}
	code, stdout, stderr = runCLI("accounts", "upload-avatar", "acc_1", "--image", filePath, "--token", "preview-secret", "--dry-run")
	var multipartPreview struct {
		Body string `json:"body"`
	}
	if err := json.Unmarshal([]byte(stdout), &multipartPreview); err != nil {
		t.Fatalf("multipart preview is not JSON: %v\n%s", err, stdout)
	}
	if code != 0 || stderr != "" || !strings.Contains(stdout, `"dry_run": true`) ||
		!strings.Contains(stdout, "multipart/form-data; boundary=") ||
		!strings.Contains(multipartPreview.Body, `name="image"; filename="preview.txt"`) ||
		!strings.Contains(multipartPreview.Body, "avatar-preview-data") ||
		strings.Contains(stdout, "preview-secret") {
		t.Errorf("multipart preview did not include the file request safely: exit %d, stdout %q, stderr %q", code, stdout, stderr)
	}

	code, stdout, stderr = runCLI("--dry-run", "api", "DELETE", "/accounts/acc_1", "--token", "preview-secret")
	if code != 0 || stderr != "" || !strings.Contains(stdout, `"method": "DELETE"`) || strings.Contains(stdout, "preview-secret") {
		t.Errorf("raw destructive preview should not need confirmation or send the request: exit %d, stdout %q, stderr %q", code, stdout, stderr)
	}
	outRoot, err := os.MkdirTemp(".", ".dry-run-output-")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(outRoot)
	outPath := filepath.Join(outRoot, "missing", "response.json")
	code, stdout, stderr = runCLI("--dry-run", "api", "GET", "/accounts", "--out", outPath)
	if code != 0 || stderr != "" || !strings.Contains(stdout, `"body": ""`) {
		t.Errorf("raw preview should include an empty body without writing output: exit %d, stdout %q, stderr %q", code, stdout, stderr)
	}
	if _, err := os.Stat(filepath.Dir(outPath)); !os.IsNotExist(err) {
		t.Errorf("dry-run created output directories: stat error %v", err)
	}
	if _, err := os.Stat(authPath()); !os.IsNotExist(err) {
		t.Errorf("dry-run wrote credentials to %s (stat error: %v)", authPath(), err)
	}

	expectFailure(t, 2, "UNKNOWN_FLAG", "--dry-run", "accounts", "create", "--name", "Preview", "--not-a-flag")
	message := expectFailure(t, 2, "INVALID_USAGE", "--dry-run", "accounts", "create", "--data", "{not json")
	if !strings.HasPrefix(message, "--data: invalid JSON") {
		t.Errorf("invalid request body message %q does not identify --data", message)
	}

	// A dry-run may inspect credentials but must not refresh or rewrite an
	// expired stored OAuth session.
	expired := storedAuth{
		Scalars: map[string]string{},
		OAuth: &oauthSession{
			AccessToken:  "expired-preview-token",
			RefreshToken: "preview-refresh-token",
			ExpiresAt:    time.Now().Add(-time.Hour).UnixMilli(),
		},
	}
	stored, err := json.Marshal(expired)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(authPath()), 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(authPath(), stored, 0600); err != nil {
		t.Fatal(err)
	}
	before := append([]byte(nil), stored...)
	code, stdout, stderr = runCLI("--dry-run", "accounts", "list")
	if code != 1 {
		t.Errorf("expired OAuth preview should fail without refreshing credentials: exit %d, stdout %q, stderr %q", code, stdout, stderr)
	}
	after, err := os.ReadFile(authPath())
	if err != nil || !bytes.Equal(after, before) {
		t.Errorf("dry-run changed stored credentials: read error %v", err)
	}
}

// hasRequiredFlag reports whether op has a required non-path parameter.
func hasRequiredFlag(op opDef) bool {
	for _, p := range op.Params {
		if p.Required && p.Kind != "path" {
			return true
		}
	}
	return false
}
